window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-692229251d5da27e"]={"versions": [{"id": "FIG-692229251d5da27e", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Simulink-Modellhierarchie (Blockdiagramm) zur Implementierung eines Kommunikationsverzögerungsblocks (<code>Communication Delay</code> / <code>BusDelay1</code>) in der AUTOSAR-Simulink-Umgebung. Das Diagramm zeigt die dreistufige funktionale Dekomposition von der Triggerebene über das Function-Call-Subsystem <code>Read</code> bis hin zur eigentlichen Leseoperation an der simulierten RTE.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Ebene 1 (<code>.../Communication Delay1/BusDelay1</code>)</strong>:\n<ul class=\"fig-list\"><li><code>com_func</code> (Inport 1, Trigger/Control-Signal): Führt über einen Bus Selector / Signal-Splitter mit dem Signal <code>&lt;Com_Update_Delay_SWC2_1&gt;</code> als Function-Call-Trigger auf den oberen Triggereingang des Subsystems <code>Read</code>.\n</li><li><code>In1</code> (Inport 2): Führt auf Dateneingang <code>In2</code> des Subsystems <code>Read</code>.\n</li><li><code>Read</code> (Function-Call-Subsystem mit <code>function()</code>, Eingang <code>In2</code>, Ausgang <code>Out1</code>).\n</li><li><code>Out1</code> (Outport 1): Empfängt das Ausgangssignal aus <code>Read</code>.\n</li></ul>\n</li><li><strong>Ebene 2 (<code>.../BusDelay1/Read</code>)</strong>:\n<ul class=\"fig-list\"><li><code>function</code> (Trigger-Block <code>f()</code>).\n</li><li><code>In2</code> (Inport 1): Führt das Signal <code>&lt;DataElement_a&gt;</code> in einen <code>Terminator</code>-Block.\n</li><li><code>RTE_Read</code> (Subsystem/Block <code>DataElement Number: 110</code>): Erzeugt das Signal <code>DataElement1</code>.\n</li><li><code>Out1</code> (Outport 1): Empfängt <code>DataElement1</code>.\n</li></ul>\n</li><li><strong>Ebene 3 (<code>.../Read...</code>)</strong>:\n<ul class=\"fig-list\"><li><code>RTE_Read</code> (S-Function / MATLAB Function / Bibliotheksblock mit Signalausgang <code>y</code>): Stellt den ausgelesenen RTE-Datenwert über Leitung <code>DataElement1</code> an den Ausgang <code>Out1</code> bereit.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ein Function-Call-Creation-Block der Software-Component-Umgebung erzeugt zu einem definierten Zeitpunkt das Triggerereignis <code>com_func</code>, welches das Signal <code>Com_Update_Delay_SWC2_1</code> aktiviert. Dadurch wird das getriggerte Subsystem <code>Read</code> ausgeführt. Innerhalb des Subsystems wird der Datenpfad von <code>In2</code> terminiert und stattdessen über den Block <code>RTE_Read</code> (identifiziert über <code>DataElement Number: 110</code>) der aktuelle Datenwert aus der simulierten RTE abgefragt und synchron an <code>Out1</code> übergeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als Entwurfsmuster für die Simulation deterministischer Kommunikationslaufzeiten (<code>maxTransferTime</code>, <code>maxJitter</code> der Connector-ComSpec). Entwickler müssen sicherstellen, dass Bus-Delay-Blöcke entsprechend parametriert werden und Lesezugriffe über die dedizierten Function-Call-Mechanismen zeitlich entkoppelt von der eigentlichen Komponentenberechnung aus der RTE erfolgen.</p>"}, {"id": "FIG-fc8067ada822027a", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Simulink-Modellhierarchie (Blockdiagramm) zur Implementierung eines Kommunikationsverzögerungsblocks (<code>Communication Delay</code> / <code>BusDelay1</code>) in der AUTOSAR-Simulink-Umgebung. Das Diagramm zeigt die dreistufige funktionale Dekomposition von der Triggerebene über das Function-Call-Subsystem <code>Read</code> bis hin zur eigentlichen Leseoperation an der simulierten RTE.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Ebene 1 (<code>.../Communication Delay1/BusDelay1</code>)</strong>:\n<ul class=\"fig-list\"><li><code>com_func</code> (Inport 1, Trigger/Control-Signal): Führt über einen Bus Selector / Signal-Splitter mit dem Signal <code>&lt;Com_Update_Delay_SWC2_1&gt;</code> als Function-Call-Trigger auf den oberen Triggereingang des Subsystems <code>Read</code>.\n</li><li><code>In1</code> (Inport 2): Führt auf Dateneingang <code>In2</code> des Subsystems <code>Read</code>.\n</li><li><code>Read</code> (Function-Call-Subsystem mit <code>function()</code>, Eingang <code>In2</code>, Ausgang <code>Out1</code>).\n</li><li><code>Out1</code> (Outport 1): Empfängt das Ausgangssignal aus <code>Read</code>.\n</li></ul>\n</li><li><strong>Ebene 2 (<code>.../BusDelay1/Read</code>)</strong>:\n<ul class=\"fig-list\"><li><code>function</code> (Trigger-Block <code>f()</code>).\n</li><li><code>In2</code> (Inport 1): Führt das Signal <code>&lt;DataElement_a&gt;</code> in einen <code>Terminator</code>-Block.\n</li><li><code>RTE_Read</code> (Subsystem/Block <code>DataElement Number: 110</code>): Erzeugt das Signal <code>DataElement1</code>.\n</li><li><code>Out1</code> (Outport 1): Empfängt <code>DataElement1</code>.\n</li></ul>\n</li><li><strong>Ebene 3 (<code>.../Read...</code>)</strong>:\n<ul class=\"fig-list\"><li><code>RTE_Read</code> (S-Function / MATLAB Function / Bibliotheksblock mit Signalausgang <code>y</code>): Stellt den ausgelesenen RTE-Datenwert über Leitung <code>DataElement1</code> an den Ausgang <code>Out1</code> bereit.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Ein Function-Call-Creation-Block der Software-Component-Umgebung erzeugt zu einem definierten Zeitpunkt das Triggerereignis <code>com_func</code>, welches das Signal <code>Com_Update_Delay_SWC2_1</code> aktiviert. Dadurch wird das getriggerte Subsystem <code>Read</code> ausgeführt. Innerhalb des Subsystems wird der Datenpfad von <code>In2</code> terminiert und stattdessen über den Block <code>RTE_Read</code> (identifiziert über <code>DataElement Number: 110</code>) der aktuelle Datenwert aus der simulierten RTE abgefragt und synchron an <code>Out1</code> übergeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als Entwurfsmuster für die Simulation deterministischer Kommunikationslaufzeiten (<code>maxTransferTime</code>, <code>maxJitter</code> der Connector-ComSpec). Entwickler müssen sicherstellen, dass Bus-Delay-Blöcke entsprechend parametriert werden und Lesezugriffe über die dedizierten Function-Call-Mechanismen zeitlich entkoppelt von der eigentlichen Komponentenberechnung aus der RTE erfolgen.</p>"}], "trans": [{"from": "FIG-692229251d5da27e", "to": "FIG-fc8067ada822027a", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
